  it('skips subsequent hooks and provider calls when beforeSession throws, passing session and error to onError and unchanged session to afterSession', async () => {
    const session = createSession('hello');
    const thrownError = new Error('beforeSession boom');
    const callOrder: string[] = [];
    const {provider, sent} = capturingProvider();
    let onErrorArgs: {sessionMatch: boolean; errorMatch: boolean} | undefined;
    let afterSessionArgs: {sessionMatch: boolean; entryCount: number} | undefined;

    const hooks: OrchestratorHooks = {
      ...recordingHooks(callOrder, [
        'beforeUserInput',
        'afterUserInput',
        'beforeModelResponse',
        'afterModelResponse',
      ]),
      beforeSession: async () => {
        callOrder.push('beforeSession');
        throw thrownError;
      },
      onError: async (receivedSession, receivedError) => {
        callOrder.push('onError');
        onErrorArgs = {sessionMatch: receivedSession === session, errorMatch: receivedError === thrownError};
      },
      afterSession: async receivedSession => {
        callOrder.push('afterSession');
        afterSessionArgs = {sessionMatch: receivedSession === session, entryCount: receivedSession.entries.length};
      },
    };

    const orchestrator = createChatOrchestrator(provider, promptBuilder, undefined, {hooks});
    const outcome = await outcomeOf(orchestrator.processMessage(session));

    expect({outcome, callOrder, sent, onErrorArgs, afterSessionArgs}).toEqual({
      outcome: 'beforeSession boom',
      callOrder: ['beforeSession', 'onError', 'afterSession'],
      sent: {systemPrompt: '', lastUserContent: ''},
      onErrorArgs: {sessionMatch: true, errorMatch: true},
